func:
// button topic: "befehl" oder "befehl:kanal", z.B. "volumeUp:2", "gain:all"
const [cmd, ch] = String(msg.topic || "").split(":");
msg.topic = cmd;
if (ch !== undefined) msg.channel = ch === "all" ? "all" : +ch;
return msg;

msg.payload = "Nota: " + (msg.error && msg.error.message);
msg.ui_update = { color: "#c62828" };
return msg;

if (msg.topic !== "status") return null;
const s = msg.payload;
const rows = [
    { Eigenschaft: "Modell", Wert: s.info.modelName + (s.info.draft ? " (Entwurf)" : "") },
    { Eigenschaft: "Seriennummer", Wert: s.info.serial }, { Eigenschaft: "Gerätename", Wert: s.name },
    { Eigenschaft: "Eingänge / Kanäle", Wert: s.layout.inputs + " / " + s.layout.outputs },
    { Eigenschaft: "Temperatur", Wert: s.supply.temperaturePct + " %" },
    { Eigenschaft: "Nickname", Wert: s.nickname || "–" },
    { Eigenschaft: "Rail", Wert: s.supply.rail + " V" }, { Eigenschaft: "Aux (?)", Wert: s.supply.aux + " V" },
    { Eigenschaft: "Geräte-Alarme", Wert: (s.alarms.machine && s.alarms.machine.flags.length) ? s.alarms.machine.flags.join(", ") : "keine" },
    { Eigenschaft: "Kanal-Alarme", Wert: (s.alarms.output || []).map((o, i) => o && o.raw ? "CH" + (i + 1) + ": " + o.flags.join(", ") : null).filter(Boolean).join("; ") || "keine" }];
const k = JSON.stringify(rows.filter(r => !/Temperatur|Rail|Aux/.test(r.Eigenschaft)));
const t = Date.now();
if (context.get("k") === k && t - (context.get("t") || 0) < 10000) return null;   // refresh analog values every 10 s
context.set("k", k); context.set("t", t);
return { payload: rows };

if (msg.topic === "status") return [{ topic: "Temperatur", payload: msg.payload.supply.temperaturePct }, null];
if (msg.topic === "meters") return [null, msg.payload.output.vRms.map((v, i) => ({ topic: "Kanal " + (i + 1), payload: v }))];
return null;

const prev = context.get("prev") || {};
let txt = null, color = "#0d74ce";
if (msg.topic === "connection") {
    if (prev.connected !== undefined && prev.connected !== msg.payload.connected) {
        txt = msg.payload.connected ? "Verbindung zum Nota wiederhergestellt" : "Verbindung zum Nota verloren: " + (msg.payload.error || "");
        color = msg.payload.connected ? "#2e7d32" : "#c62828";
    }
    prev.connected = msg.payload.connected;
} else if (msg.topic === "status") {
    const a = msg.payload.alarms.any;
    const al = msg.payload.alarms;
    const flags = [...((al.machine && al.machine.flags) || []), ...(al.output || []).flatMap((o, i) => o && o.raw ? o.flags.map(x => "CH" + (i + 1) + " " + x) : [])];
    if (prev.any === false && a) { txt = "Nota Alarm: " + (flags.join(", ") || ("Status " + msg.payload.state + "/" + msg.payload.statusCode)); color = "#f9a825"; }
    if (prev.any === true && !a) { txt = "Nota: keine Alarme mehr"; color = "#2e7d32"; }
    prev.any = a;
}
context.set("prev", prev);
if (!txt) return null;
return { payload: txt, ui_update: { color } };
